  const sha = lines[i].split(/\s+/)[2];
  const buf = git('cat-file', 'blob', sha);
  const local = './peek/' + String(i).padStart(2, '0') + '.md';
  fs.writeFileSync(local, buf);
  idx.push(local + ' <= ' + name + '  (' + buf.toString('utf8').split('\n').length + ' lines)');
});
fs.writeFileSync('./peek/_index.txt', idx.join('\n'), 'utf8');

